User: Write a K program that prompts the user for a file name to read in CSV format and a specified value to search for. The program should then count the number of rows in the file that contain the specified value and display the result to the user. The program should handle errors such as incorrect file name, invalid delimiter, and missing specified value. It should also provide a clear and user-friendly output format.
Assistant: // CSV file reader and search program in K

// Import required libraries
import IO
import CSV

// Define the main function
def main() -> Int {

    // Prompt the user for the CSV file name
    println("Enter the name of the CSV file:")
    file_name:Str <- Console.readLine()

    // Prompt the user for the specified value to search for
    println("Enter the value to search for:")
    search_value:Str <- Console.readLine()

    // Initialize the row count
    row_count:Int <- 0

    // Try to open the CSV file
    try {
        // Specify the delimiter as a comma (",")
        delimiter:Str <- ","
        file:IO.FD <- open(file_name, IO.r)
        csv_file:CSV.Data <- CSV.read(file, delimiter)
        close(file)

        // Check if the CSV file is empty
        if len(csv_file) == 0 {
            println("The CSV file is empty.")
            return 0
        }

        // Loop through the rows of the CSV file and count the number of rows that contain the specified value
        for row in csv_file {
            if search_value in row {
                row_count <- row_count + 1
            }
        }

        // Display the result to the user
        println("The CSV file contains " + row_count + " rows that contain \"" + search_value + "\".")

    }
    // Catch errors and handle them
    catch e:Exception {
        println("Error: " + e.message)
        return 0
    }

    // Return 1 to indicate successful execution
    return 1
}

// Call the main function
main()
